function solve(input) {
  const seen = new Set();
  const balances = new Map();

  for (const { eventId, account, delta } of input) {
    if (seen.has(eventId)) continue;
    seen.add(eventId);
    balances.set(account, (balances.get(account) || 0) + delta);
  }

  const result = Array.from(balances.entries());
  result.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return result;
}
