function solve(input) {
  // Create a shallow copy of the input to avoid mutation
  const ops = input.slice();

  // Map to store the highest version and corresponding operation for each key
  const latest = new Map();

  for (const { key, version, op, value } of ops) {
    const existing = latest.get(key);
    if (!existing || version > existing.version) {
      latest.set(key, { version, op, value });
    }
  }

  // Build the result object with a null prototype to avoid prototype pollution
  const result = Object.create(null);

  for (const [key, { op, value }] of latest.entries()) {
    if (op === 'set') {
      result[key] = value;
    } // else op === 'delete', do nothing
  }

  return result;
}
