function solve(input) {
  const { nodes, edges } = input;

  // Build adjacency list and indegree map
  const adj = new Map();
  const indeg = new Map();

  // Initialize maps
  for (const n of nodes) {
    adj.set(n, new Set());
    indeg.set(n, 0);
  }

  // Process edges, ignoring duplicates
  const seen = new Set();
  for (const [u, v] of edges) {
    if (!nodes.includes(u) || !nodes.includes(v)) continue; // safety
    const key = u + '->' + v;
    if (seen.has(key)) continue;
    seen.add(key);
    if (u === v) { // self-loop -> cycle
      return null;
    }
    adj.get(u).add(v);
    indeg.set(v, indeg.get(v) + 1);
  }

  // Priority queue: use array sorted lexicographically
  const zero = [];
  for (const n of nodes) {
    if (indeg.get(n) === 0) zero.push(n);
  }
  zero.sort();

  const result = [];
  while (zero.length) {
    const u = zero.shift(); // smallest lexicographically
    result.push(u);

    for (const v of adj.get(u)) {
      indeg.set(v, indeg.get(v) - 1);
      if (indeg.get(v) === 0) {
        // insert v into zero keeping sorted order
        let i = 0;
        while (i < zero.length && zero[i] < v) i++;
        zero.splice(i, 0, v);
      }
    }
  }

  // If all nodes processed, return result; else cycle exists
  return result.length === nodes.length ? result : null;
}
