function solve(input) {
  const ops = input.map(o => ({ ...o })); // shallow copy to avoid mutation
  const store = new Map(); // key -> {value, expire}
  const results = [];

  for (const op of ops) {
    const { t, op: type } = op;

    if (type === 'put') {
      const { key, value, ttl } = op;
      const expire = t + ttl;
      store.set(key, { value, expire });
    } else if (type === 'get') {
      const { key } = op;
      const entry = store.get(key);
      if (entry && entry.expire > t) {
        results.push(entry.value);
      } else {
        results.push(null);
        if (entry) store.delete(key); // clean up expired
      }
    } else if (type === 'delete') {
      const { key } = op;
      store.delete(key);
    }
  }

  return results;
}
