function solve(input) {
  const { document, pointer } = input;

  // Helper to check if a value is a plain object (own properties only)
  const isObject = (val) => typeof val === 'object' && val !== null && !Array.isArray(val);

  // Parse pointer into tokens
  const tokens = (() => {
    if (pointer === '') return [];
    if (!pointer.startsWith('/')) return null; // invalid format
    return pointer
      .slice(1)
      .split('/')
      .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));
  })();

  if (tokens === null) {
    return { found: false };
  }

  let current = document;
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (Array.isArray(current)) {
      // Array index must be a canonical nonnegative decimal integer
      if (!/^[0-9]+$/.test(token)) {
        return { found: false };
      }
      const idx = Number(token);
      if (idx < 0 || !Number.isInteger(idx)) {
        return { found: false };
      }
      if (idx >= current.length) {
        return { found: false };
      }
      current = current[idx];
    } else if (isObject(current)) {
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return { found: false };
      }
      current = current[token];
    } else {
      // Primitive value encountered before end of pointer
      return { found: false };
    }
  }

  return { found: true, value: current };
}
